create table if not exists subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_code text not null default 'FREE' check(plan_code in ('FREE','FAMILY','PROFESSIONAL','BUSINESS','ENTERPRISE')),status text not null default 'ACTIVE' check(status in ('TRIALING','ACTIVE','PAST_DUE','CANCELLED')),provider text,provider_customer_id text,provider_subscription_id text,current_period_start timestamptz,current_period_end timestamptz,created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id));
create table if not exists billing_events(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,event_type text not null,provider text,payload jsonb not null default '{}',created_at timestamptz default now());
create table if not exists workflow_cases(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations(id) on delete cascade,entity_id uuid references organization_entities(id) on delete set null,owner_id uuid not null references auth.users(id) on delete cascade,assessment_id uuid references zakat_assessments(id) on delete set null,title text not null,status text not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists workflow_events(id uuid primary key default gen_random_uuid(),case_id uuid not null references workflow_cases(id) on delete cascade,actor_id uuid references auth.users(id),event_type text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists report_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,report_type text not null,status text not null default 'PENDING',parameters jsonb not null default '{}',result_url text,error text,created_at timestamptz not null default now(),completed_at timestamptz);
create index if not exists idx_workflow_owner on workflow_cases(owner_id,created_at desc); create index if not exists idx_report_jobs_user on report_jobs(user_id,created_at desc);
alter table organizations enable row level security; alter table organization_members enable row level security; alter table organization_entities enable row level security; alter table consolidated_assessments enable row level security; alter table organization_invitations enable row level security; alter table subscriptions enable row level security; alter table billing_events enable row level security; alter table workflow_cases enable row level security; alter table workflow_events enable row level security; alter table report_jobs enable row level security;
create policy org_membership_read on organizations for select using(owner_user_id=auth.uid() or exists(select 1 from organization_members m where m.organization_id=id and m.user_id=auth.uid()));
create policy org_owner_write on organizations for all using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid());
create policy org_member_read on organization_members for select using(user_id=auth.uid() or exists(select 1 from organization_members m where m.organization_id=organization_members.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN')));
create policy org_member_manage on organization_members for all using(exists(select 1 from organization_members m where m.organization_id=organization_members.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN'))) with check(exists(select 1 from organization_members m where m.organization_id=organization_members.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN')));
create policy entity_org_access on organization_entities for all using(exists(select 1 from organization_members m where m.organization_id=organization_entities.organization_id and m.user_id=auth.uid())) with check(exists(select 1 from organization_members m where m.organization_id=organization_entities.organization_id and m.user_id=auth.uid()));
create policy consolidated_org_access on consolidated_assessments for all using(exists(select 1 from organization_members m where m.organization_id=consolidated_assessments.organization_id and m.user_id=auth.uid())) with check(exists(select 1 from organization_members m where m.organization_id=consolidated_assessments.organization_id and m.user_id=auth.uid()));
create policy invitation_admin on organization_invitations for all using(exists(select 1 from organization_members m where m.organization_id=organization_invitations.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN'))) with check(exists(select 1 from organization_members m where m.organization_id=organization_invitations.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN')));
create policy subscription_self on subscriptions for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy billing_self on billing_events for select using(user_id=auth.uid()); create policy workflow_owner on workflow_cases for all using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy workflow_events_owner on workflow_events for select using(exists(select 1 from workflow_cases c where c.id=case_id and c.owner_id=auth.uid())); create policy report_self on report_jobs for all using(user_id=auth.uid()) with check(user_id=auth.uid());